            System.out.println("A= " + System.currentTimeMillis() + " i=" + myThread13.getI());

            myThread13.resume();
            Thread.sleep(5000);
            myThread13.suspend();
            System.out.println("B= " + System.currentTimeMillis() + " i=" + myThread13.getI());
            Thread.sleep(5000);
            System.out.println("B= " + System.currentTimeMillis() + " i=" + myThread13.getI());

